1	/* =============================================================================
2	   Boppa Llewyn × Starlight
3	
4	   The Boppa Llewyn design system on Starlight, the theme Doctored's documentation
5	   site wears (its public-docs/src/styles/custom.css), carried over rule for rule so
6	   the two sites look like one family; only Prettier's formatting differs. Change it there and here together. Frame Job's own
7	   components are styled in frame-job.css, which loads after this file.
8	
9	   This file is unlayered, so it wins over every Starlight cascade layer. The
10	   @font-face rules are in src/fonts/font-face.css and the Expressive Code settings
11	   in astro.config.mjs.
12	   ============================================================================= */
13	
14	/* --- Boppa Llewyn tokens, verbatim from the design system --------------- */
15	:root {
16	  --bl-cream: #fbf8f1;
17	  --bl-cream-1: #f4efe2;
18	  --bl-cream-2: #eae3d2;
19	  --bl-ink: #101915;
20	  --bl-on-cream-2: #40483f;
21	  --bl-on-cream-3: #6b7268;
22	
23	  --bl-bg-0: oklch(0.16 0.011 70);
24	  --bl-bg-1: oklch(0.195 0.012 70);
25	  --bl-bg-2: oklch(0.23 0.013 70);
26	  --bl-bg-3: oklch(0.275 0.014 70);
27	  --bl-line-1: oklch(0.32 0.015 72);
28	  --bl-line-2: oklch(0.43 0.018 75);
29	  --bl-fg-1: oklch(0.94 0.014 88);
30	  --bl-fg-2: oklch(0.74 0.02 82);
31	  --bl-fg-3: oklch(0.57 0.018 78);
32	
33	  --bl-brass: #f2c14e;
34	  --bl-brass-strong: #e0ab33;
35	  --bl-brass-dim: oklch(0.3 0.05 84);
36	  --bl-brass-faint: oklch(0.225 0.028 84);
37	
38	  --bl-teal: #1f8564;
39	  --bl-teal-dim: oklch(0.26 0.04 165);
40	  --bl-ember: #f4653f;
41	  --bl-ember-dim: oklch(0.27 0.05 40);
42	  --bl-danger: oklch(0.63 0.14 25);
43	  --bl-danger-dim: oklch(0.25 0.05 25);
44	
45	  /* darkened brass for cream surfaces — brass itself fails contrast on cream */
46	  --bl-brass-deep: #8a6410;
47	  --bl-brass-deeper: #5c4208;
48	  --bl-brass-pale: #f7e9c5;
49	
50	  --bl-radius-1: 2px;
51	  --bl-radius-2: 4px;
52	  --bl-radius-3: 8px;
53	  --bl-ease: cubic-bezier(0.2, 0.8, 0.2, 1);
54	  --bl-dur-fast: 120ms;
55	  --bl-dur-base: 200ms;
56	
57	  --bl-font-display: 'Cormorant Garamond', Georgia, 'Times New Roman', serif;
58	}
59	
60	/* --- Type and layout ---------------------------------------------------- */
61	:root {
62	  --sl-font: 'IBM Plex Sans', system-ui, sans-serif;
63	  --sl-font-mono: 'IBM Plex Mono', ui-monospace, monospace;
64	
65	  --sl-text-body: 0.9375rem; /* 15px */
66	  --sl-text-body-sm: 0.8125rem; /* 13px */
67	  --sl-text-code: 0.8125rem;
68	  --sl-text-code-sm: 0.75rem;
69	  --sl-line-height: 1.55;
70	  --sl-line-height-headings: 1.06;
71	
72	  /* Cormorant sits small on its em, so display sizes run large */
73	  --sl-text-h1: 2.625rem;
74	  --sl-text-h2: 1.875rem;
75	  --sl-text-h3: 1.5rem;
76	  --sl-text-h4: 1.25rem;
77	  --sl-text-h5: 1.0625rem;
78	
79	  --sl-nav-height: 3.75rem; /* 60px, per the site header */
80	  --sl-sidebar-width: 17.5rem;
81	  --sl-content-width: 42.5rem; /* --measure-prose, 680px */
82	}
83	
84	@media (min-width: 50em) {
85	  :root {
86	    --sl-nav-height: 3.75rem;
87	    --sl-nav-pad-x: 1.5rem;
88	    --sl-text-h1: 3.25rem; /* 52px, --text-3xl */
89	    --sl-text-h2: 2.375rem; /* 38px */
90	    --sl-text-h3: 1.75rem;
91	    --sl-text-h4: 1.3125rem;
92	  }
93	}
94	
95	/* --- Colour: dark (default) --------------------------------------------- */
96	:root,
97	::backdrop {
98	  --sl-color-white: var(--bl-fg-1);
99	  --sl-color-gray-1: var(--bl-fg-1);
100	  --sl-color-gray-2: var(--bl-fg-2);
101	  --sl-color-gray-3: var(--bl-fg-3);
102	  --sl-color-gray-4: var(--bl-line-2);
103	  --sl-color-gray-5: var(--bl-bg-3);
104	  --sl-color-gray-6: var(--bl-bg-1);
105	  --sl-color-gray-7: var(--bl-bg-2);
106	  --sl-color-black: var(--bl-bg-0);
107	
108	  --sl-color-accent-low: var(--bl-brass-faint);
109	  --sl-color-accent: var(--bl-brass);
110	  --sl-color-accent-high: var(--bl-brass);
111	
112	  --sl-color-text: var(--bl-fg-2);
113	  --sl-color-text-accent: var(--bl-brass);
114	  --sl-color-text-invert: var(--bl-ink);
115	  --sl-color-bg: var(--bl-bg-0);
116	  --sl-color-bg-nav: var(--bl-bg-0);
117	  --sl-color-bg-sidebar: var(--bl-bg-1);
118	  --sl-color-bg-inline-code: var(--bl-bg-2);
119	  --sl-color-bg-accent: var(--bl-brass);
120	  --sl-color-hairline-light: var(--bl-line-1);
121	  --sl-color-hairline: var(--bl-line-1);
122	  --sl-color-hairline-shade: var(--bl-line-1);
123	  --sl-color-backdrop-overlay: rgba(10, 9, 8, 0.65);
124	
125	  /* Aside hues remapped onto the palette: note→teal, tip→brass,
126	     caution→ember, danger→danger. Starlight has no separate green/blue use. */
127	  --sl-color-blue-low: var(--bl-teal-dim);
128	  --sl-color-blue: var(--bl-teal);
129	  --sl-color-blue-high: #8ad8b9;
130	  --sl-color-green-low: var(--bl-teal-dim);
131	  --sl-color-green: var(--bl-teal);
132	  --sl-color-green-high: #8ad8b9;
133	  --sl-color-purple-low: var(--bl-brass-faint);
134	  --sl-color-purple: var(--bl-brass);
135	  --sl-color-purple-high: var(--bl-brass);
136	  --sl-color-orange-low: var(--bl-ember-dim);
137	  --sl-color-orange: var(--bl-ember);
138	  --sl-color-orange-high: #ffa487;
139	  --sl-color-red-low: var(--bl-danger-dim);
140	  --sl-color-red: var(--bl-danger);
141	  --sl-color-red-high: #f6aa9e;
142	
143	  /* Shadows exist for true overlays only */
144	  --sl-shadow-sm: 0 1px 2px rgba(0, 0, 0, 0.4);
145	  --sl-shadow-md: 0 4px 16px rgba(0, 0, 0, 0.45);
146	  --sl-shadow-lg: 0 16px 48px rgba(0, 0, 0, 0.55);
147	}
148	
149	/* --- Colour: cream (light) --------------------------------------------- */
150	:root[data-theme='light'],
151	[data-theme='light'],
152	[data-theme='light'] ::backdrop {
153	  --sl-color-white: var(--bl-ink);
154	  --sl-color-gray-1: #1a2620;
155	  --sl-color-gray-2: var(--bl-on-cream-2);
156	  --sl-color-gray-3: var(--bl-on-cream-3);
157	  --sl-color-gray-4: #98a093;
158	  --sl-color-gray-5: var(--bl-cream-2);
159	  --sl-color-gray-6: var(--bl-cream-1);
160	  --sl-color-gray-7: #f8f5ec;
161	  --sl-color-black: var(--bl-cream);
162	
163	  --sl-color-accent-low: var(--bl-brass-pale);
164	  --sl-color-accent: var(--bl-brass-deep);
165	  --sl-color-accent-high: var(--bl-brass-deeper);
166	
