333	/* --- Header: the one blurred surface in the system ---------------------- */
334	header.header {
335	  background-color: color-mix(in srgb, var(--sl-color-bg) 85%, transparent);
336	  backdrop-filter: blur(12px);
337	  border-bottom: 1px solid var(--sl-color-hairline-shade);
338	}
339	
340	/* --- Links, buttons, motion -------------------------------------------- */
341	.sl-markdown-content a:not(:where(.sl-link-card, .sl-link-button, .not-content *)) {
342	  color: var(--sl-color-text-accent);
343	  text-decoration: none;
344	  text-underline-offset: 0.2em;
345	  transition: color var(--bl-dur-fast) var(--bl-ease);
346	}
347	
348	.sl-markdown-content a:not(:where(.sl-link-card, .sl-link-button, .not-content *)):hover {
349	  color: var(--sl-color-accent-high);
350	  text-decoration: underline;
351	}
352	
353	.sl-link-button.primary {
354	  background: var(--bl-brass);
355	  color: var(--bl-ink);
356	  border: 1px solid transparent;
357	  font-weight: 500;
358	}
359	
360	.sl-link-button.primary:hover {
361	  background: var(--bl-brass-strong);
362	  color: var(--bl-ink);
363	  text-decoration: none;
364	}
365	
366	.sl-link-button.secondary {
367	  background: var(--sl-color-gray-6);
368	  color: var(--sl-color-white);
369	  border: 1px solid var(--sl-color-hairline-light);
370	}
371	
372	.sl-link-button.secondary:hover {
373	  background: var(--sl-color-gray-7);
374	  border-color: var(--sl-color-gray-4);
375	}
376	
377	.sl-link-button.minimal {
378	  color: var(--sl-color-text-accent);
379	}
380	
381	/* Nothing scales or shrinks; opacity and colour only */
382	a,
383	button,
384	summary,
385	.sl-link-card {
386	  transition:
387	    background-color var(--bl-dur-fast) var(--bl-ease),
388	    border-color var(--bl-dur-fast) var(--bl-ease),
389	    color var(--bl-dur-fast) var(--bl-ease);
390	}
391	
392	/* --- Focus: 2px page-coloured offset plus a 4px brass ring ------------- */
393	:is(a, button, summary, input, select, [tabindex]):focus-visible {
394	  outline: none;
395	  box-shadow:
396	    0 0 0 2px var(--sl-color-bg),
397	    0 0 0 4px var(--sl-color-accent);
398	  border-radius: var(--bl-radius-1);
399	}
400	
401	@media (prefers-reduced-motion: reduce) {
402	  * {
403	    transition-duration: 0.01ms !important;
404	  }
405	}
406	
407	/* =============================================================================
408	   Site layer — the parts of the design the token file above cannot reach.
409	
410	   Everything here is unlayered too, so it beats Starlight's own
411	   `starlight.core` / `starlight.components` / `starlight.content` layers
412	   regardless of specificity. Values come from the handoff's screen notes;
413	   where the notes and `starlight-custom.css` disagree, the CSS above wins.
414	   ============================================================================= */
415	
416	/* --- Layout metrics ----------------------------------------------------- */
417	:root {
418	  --sl-content-pad-x: 1.5rem; /* 24px gutter, the design's container inset */
419	}
420	
421	/* Splash pages (no sidebar) run to the design's 1120px container rather than
422	   Starlight's 1080px. The extra `[data-has-hero]` lifts specificity over the
423	   `html:not([data-has-sidebar])` rule Starlight inlines in <head>. */
424	html[data-has-hero]:not([data-has-sidebar]) {
425	  --sl-content-width: 70rem;
426	}
427	
428	/* --- Header controls ---------------------------------------------------- */
429	/* The mobile menu button ships as a filled circle with a shadow. The system
430	   has no filled circles and no shadows outside true overlays, so it becomes a
431	   32px hairline square. 32px is under the 44px minimum touch target, so the
432	   hit area is expanded past the visual box with a pseudo-element. */
433	.sl-menu-button {
434	  border: 1px solid var(--sl-color-hairline-light);
435	  border-radius: var(--bl-radius-1);
436	  background-color: var(--sl-color-bg);
437	  color: var(--sl-color-gray-1);
438	  box-shadow: none;
439	}
440	
441	.sl-menu-button:hover {
442	  background-color: var(--sl-color-gray-6);
443	  border-color: var(--sl-color-gray-4);
444	  color: var(--sl-color-white);
445	}
446	
447	.sl-menu-button:has(~ :popover-open) {
448	  background-color: var(--sl-color-gray-6);
449	  border-color: var(--sl-color-gray-4);
450	  color: var(--sl-color-white);
451	  box-shadow: none;
452	}
453	
454	/* 32px box, 44px target: the pseudo-element is the thing the finger hits. */
455	.sl-menu-button::after {
456	  content: '';
457	  position: absolute;
458	  inset: calc((var(--sl-menu-button-size) - 2.75rem) / 2);
459	}
460	
461	/* Below the sidebar breakpoint the search control is an icon button; the design
462	   draws it as a 32px hairline square, again with a 44px hit area. */
463	@media (max-width: 50rem) {
464	  site-search button[data-open-modal] {
465	    position: relative;
466	    width: var(--sl-menu-button-size);
467	    height: var(--sl-menu-button-size);
468	    justify-content: center;
469	    padding: 0;
470	    border: 1px solid var(--sl-color-hairline-light);
471	    border-radius: var(--bl-radius-1);
472	    background-color: transparent;
473	    color: var(--sl-color-gray-1);
474	  }
475	
476	  site-search button[data-open-modal]::after {
477	    content: '';
478	    position: absolute;
479	    inset: calc((var(--sl-menu-button-size) - 2.75rem) / 2);
480	  }
481	
482	  site-search button[data-open-modal] svg {
483	    font-size: 1rem;
484	  }
485	}
486	
487	/* --- Sidebar ------------------------------------------------------------ */
488	.sidebar-content {
489	  padding: 2rem var(--sl-sidebar-pad-x);
490	}
491	
492	/* 28px between top-level groups */
493	.sidebar-content .top-level > li + li {
494	  margin-top: 1.75rem;
495	}
496	
497	.sidebar-content .group-label .large {
498	  color: var(--sl-color-gray-3);
499	}
500	
501	.sidebar-content summary {
502	  padding-inline: var(--sl-sidebar-item-padding-inline, 0.5rem);
503	}
504	
505	.sidebar-content a {
506	  font-size: var(--sl-text-sm);
507	  padding: 0.375rem 0.5rem;
508	  border-radius: var(--bl-radius-2);
509	}
510	
511	/* Guarded against `[aria-current]` so the brass current-page pill survives a
512	   hover — an unlayered `a:hover` would otherwise outrank Starlight's rule. */
513	.sidebar-content a:not([aria-current='page']):is(:hover, :focus-visible) {
514	  background-color: var(--sl-color-gray-6);
515	  color: var(--sl-color-white);
516	}
517	
518	/* --- Table of contents -------------------------------------------------- */
519	.right-sidebar-panel h2 {
520	  color: var(--sl-color-gray-3);
521	  margin-bottom: 0.75rem;
522	}
523	
524	.right-sidebar-panel nav > ul {
525	  border-inline-start: 1px solid var(--sl-color-hairline-light);
526	}
527	
528	.right-sidebar-panel nav a {
529	  --pad-inline: 0.75rem; /* + the 2px rail below = the design's 14px */
530	  border-radius: 0;
531	  border-inline-start: 2px solid transparent;
532	  margin-inline-start: -1px; /* sit the rail on top of the list hairline */
533	  font-size: var(--sl-text-xs);
534	  padding-block: 0.3125rem;
535	}
536	
537	.right-sidebar-panel nav a[aria-current='true'] {
538	  border-inline-start-color: var(--sl-color-accent);
539	  color: var(--sl-color-white);
540	}
541	
542	/* Mobile ToC bar: a flat 48px strip, not a bordered pill in a bar. */
543	mobile-starlight-toc nav {
544	  background-color: var(--sl-color-bg-sidebar);
545	  border-top: 0;
546	}
547	
548	mobile-starlight-toc summary {
549	  border-bottom: 1px solid var(--sl-color-hairline-light);
550	  font-size: var(--sl-text-sm);
551	  padding-inline: var(--sl-content-pad-x);
552	}
553	
554	mobile-starlight-toc .toggle {
555	  border: 0;
556	  border-radius: 0;
557	  background-color: transparent;
558	  padding-inline: 0;
559	  gap: 0.5rem;
560	}
561	
562	mobile-starlight-toc .toggle .caret {
563	  order: -1; /* chevron leads the label, as drawn */
564	}
565	
566	mobile-starlight-toc details[open] .toggle {
567	  border-color: transparent;
568	  color: var(--sl-color-white);
569	}
570	
571	mobile-starlight-toc .display-current {
572	  margin-inline-start: auto; /* the design parks it at the end of the bar */
573	  font-size: 0.6875rem; /* 11px */
574	  color: var(--sl-color-gray-3);
575	}
576	
577	mobile-starlight-toc .dropdown {
578	  background-color: var(--sl-color-bg-sidebar);
579	  border-color: var(--sl-color-hairline-light);
580	  box-shadow: none;
581	}
582	
583	/* --- The page opener ---------------------------------------------------- */
584	/* Sections breathe: 56px above the title, 144px below the last block. The
585	   hairline between the two panels is Starlight's own and is already token'd. */
586	.content-panel {
587	  padding-block: 2rem;
588	}
589	
590	.content-panel:first-of-type {
591	  padding-block-start: 3.5rem;
592	}
593	
594	.content-panel:last-of-type {
595	  padding-block-end: 9rem;
596	}
597	
598	.page-eyebrow {
599	  font-family: var(--sl-font-mono);
600	  font-weight: 500;
601	  font-size: 0.75rem;
602	  letter-spacing: 0.08em;
603	  text-transform: uppercase;
604	  color: var(--sl-color-accent);
605	}
606	
607	.page-description {
608	  font-size: 1.0625rem; /* 17px */
609	  line-height: 1.5;
610	  color: var(--sl-color-gray-2);
611	}
612	
613	/* --- Splash ------------------------------------------------------------- */
614	@media (min-width: 50rem) {
615	  .hero {
616	    grid-template-columns: minmax(0, 1fr) 300px;
617	    gap: 4rem;
618	    padding-block: 7rem 6rem;
619	  }
620	
621	  .hero > img,
622	  .hero > .hero-html {
623	    width: 300px;
624	    margin-inline-start: auto;
625	  }
626	}
627	
628	.hero h1 {
629	  font-size: clamp(3.25rem, 7vw, 5.5rem);
630	}
631	
632	.hero .tagline {
633	  font-size: 1.1875rem; /* 19px */
634	  line-height: 1.5;
635	  max-width: 44ch;
636	}
637	
638	.hero .actions {
639	  gap: 1rem;
640	}
641	
642	/* The hero pads itself 112/96, so the panel contributes nothing above it; the
643	   144px below the last block stays with the panel. */
644	[data-has-hero] .content-panel {
645	  padding-block: 0 9rem;
646	}
647	
648	/* A hairline, then "Next steps" — 80px above it. */
649	[data-has-hero] .content-panel .sl-markdown-content {
650	  margin-top: 0;
651	  border-top: 1px solid var(--sl-color-hairline-light);
652	  padding-block: 5rem 0;
653	}
654	
655	/* --- Cards -------------------------------------------------------------- */
656	.card-grid {
657	  gap: 1.25rem;
658	}
659	
660	@media (min-width: 50rem) {
661	  .card-grid {
662	    gap: 1.25rem;
663	  }
664	
665	  .card-grid.stagger {
666	    --stagger-height: 3rem;
667	  }
668	}
669	
670	.card,
671	.sl-link-card {
672	  padding: 1.5rem;
673	}
674	
675	.card {
676	  gap: 0.75rem;
677	}
678	
679	.sl-link-card .title {
680	  font-family: var(--bl-font-display);
681	  font-weight: 500;
682	  font-size: var(--sl-text-h4);
683	  letter-spacing: -0.005em;
684	  line-height: 1.06;
685	}
686	
687	/* Starlight's Card title is a <p>, so the display-type rule above misses it. */
688	.card .title {
689	  font-family: var(--bl-font-display);
690	  font-weight: 500;
691	  font-size: 1.5rem;
692	  letter-spacing: -0.005em;
693	  line-height: 1.06;
694	  gap: 0.75rem;
695	}
696	
697	/* The stock icon chip cycles four hues by position. The system has one accent,
698	   so the chip is a hairline box and the mark is brass. */
699	.card .icon {
700	  border-color: var(--sl-color-hairline-light);
701	  background-color: transparent;
702	  border-radius: var(--bl-radius-1);
703	  color: var(--sl-color-accent);
704	}
705	
706	.card .body {
707	  font-size: var(--sl-text-sm);
708	  line-height: 1.55;
709	  color: var(--sl-color-gray-2);
710	}
711	
712	/* --- Buttons ------------------------------------------------------------ */
713	.sl-link-button {
714	  font-size: var(--sl-text-body);
715	  padding: 0.6875rem 1.375rem; /* 11px 22px */
716	}
717	
718	@media (min-width: 50rem) {
719	  .sl-link-button {
720	    font-size: var(--sl-text-body);
721	    padding: 0.6875rem 1.375rem;
722	  }
723	}
724	
725	.sl-link-button.minimal {
726	  padding-inline: 0;
727	}
728	
729	.sl-link-button svg {
730	  width: 1rem;
731	  height: 1rem;
732	}
733	
734	/* --- Code, tables, kbd -------------------------------------------------- */
735	.expressive-code figcaption {
736	  background-color: var(--sl-color-gray-6);
737	  border-bottom: 1px solid var(--sl-color-hairline-light);
738	}
739	
740	.sl-markdown-content pre:not(:where(.not-content *)) {
741	  border-color: var(--sl-color-hairline-light);
742	  border-radius: var(--bl-radius-2);
743	}
744	
745	.sl-markdown-content blockquote:not(:where(.not-content *)) {
746	  border-inline-start-color: var(--sl-color-hairline-light);
747	}
748	
749	/* Starlight makes tables `display: block` so wide ones scroll on their own.
750	   The design asks for a full-width table instead, which needs a real table box. */
751	.sl-markdown-content table:not(:where(.not-content *)) {
752	  display: table;
753	  width: 100%;
754	}
755	
756	/* Commands and identifiers in tables never break mid-token. */
757	.sl-markdown-content :is(th, td) > code {
758	  white-space: nowrap;
759	}
760	
761	.sl-markdown-content kbd {
762	  font-family: var(--sl-font-mono);
763	  background-color: var(--sl-color-gray-5);
764	  border: 1px solid var(--sl-color-hairline-light);
765	  padding: 0.125rem 0.375rem;
766	}
767	
768	/* --- Footer ------------------------------------------------------------- */
769	/* Footer fine print is mono and factual. Nothing renders here until `editLink`
770	   or `lastUpdated` is switched on in the Starlight config; this is so that it
771	   arrives already themed when it is. */
772	footer .meta,
773	footer .kudos {
774	  font-family: var(--sl-font-mono);
775	  font-size: 0.75rem;
776	  color: var(--sl-color-gray-3);
777	}
778	
779	/* --- Pagination --------------------------------------------------------- */
780	/* The prev/next links are cards, and cards take a hairline and no shadow. */
781	.pagination-links a {
782	  border-radius: var(--bl-radius-2);
783	  border-color: var(--sl-color-hairline-light);
784	  box-shadow: none;
785	}
786	
787	.pagination-links a:hover {
788	  background-color: var(--sl-color-gray-6);
789	  border-color: var(--sl-color-gray-4);
790	}
791	
792	.pagination-links .link-title {
793	  color: var(--sl-color-white);
794	  font-size: var(--sl-text-h4);
795	}
796	
797	/* --- Search ------------------------------------------------------------- */
798	site-search kbd {
799	  font-family: var(--sl-font-mono);
800	  border-radius: var(--bl-radius-1);
801	}
802	
803	site-search button[data-open-modal] {
804	  background-color: var(--sl-color-gray-6);
805	  border-color: var(--sl-color-hairline-light);
806	}
807	
808	site-search button[data-open-modal]:hover {
809	  background-color: var(--sl-color-gray-7);
810	  border-color: var(--sl-color-gray-4);
811	  color: var(--sl-color-white);
812	}
813	
814	#starlight__search {
815	  --pagefind-ui-border-radius: var(--bl-radius-1);
816	  --pagefind-ui-background: var(--sl-color-gray-6);
817	  --pagefind-ui-border: var(--sl-color-hairline-light);
818	}
819	
820	#starlight__search input:focus {
821	  --pagefind-ui-border: var(--sl-color-accent);
822	}
823

