const { description } = entry.data;
---

{eyebrow && <p class="page-eyebrow">{eyebrow}</p>}
<h1 id={PAGE_TITLE_ID}>{entry.data.title}</h1>
{description && <p class="page-description">{description}</p>}

<style>
  @layer starlight.core {
    h1 {
      font-size: var(--sl-text-h1);
      line-height: var(--sl-line-height-headings);
    }

    .page-eyebrow + h1 {
      margin-top: 1.25rem;
    }

    h1 + .page-description {
      margin-top: 1rem;
    }
  }
</style>
---
/* Starlight's Hero, plus the mono eyebrow the system puts above every h1.
   The layout below is Starlight's own, kept because overriding a component
   replaces its scoped CSS; the design's splash values live in custom.css. */
import { Image } from 'astro:assets';
import DraftContentNotice from '@astrojs/starlight/components/DraftContentNotice.astro';
import { LinkButton } from '@astrojs/starlight/components';

/** Starlight's id for the top-of-page anchor the skip link targets. */
const PAGE_TITLE_ID = '_top';

const { data } = Astro.locals.starlightRoute.entry;
const { title = data.title, tagline, image, actions = [] } = data.hero || {};
const { eyebrow } = data;

const imageAttrs = {
  loading: 'eager' as const,
  decoding: 'async' as const,
  width: 400,
  height: 400,
  alt: image?.alt || '',
};

let darkImage: ImageMetadata | undefined;
let lightImage: ImageMetadata | undefined;
let rawHtml: string | undefined;
if (image) {
  if ('file' in image) {
    darkImage = image.file;
  } else if ('dark' in image) {
    darkImage = image.dark;
    lightImage = image.light;
  } else {
    rawHtml = image.html;
  }
}
---

<div class="hero">
  {darkImage && (
    <Image
      src={darkImage}
      {...imageAttrs}
      class:list={{ 'light:sl-hidden': Boolean(lightImage) }}
    />
  )}
  {lightImage && <Image src={lightImage} {...imageAttrs} class="dark:sl-hidden" />}
  {rawHtml && <div class="hero-html sl-flex" set:html={rawHtml} />}
  <div class="sl-flex stack">
    <div class="sl-flex copy">
      {eyebrow && <p class="page-eyebrow">{eyebrow}</p>}
      <h1 id={PAGE_TITLE_ID} data-page-title set:html={title} />
      {data.draft && <DraftContentNotice />}
      {tagline && <div class="tagline" set:html={tagline} />}
    </div>
    {actions.length > 0 && (
      <div class="sl-flex actions">
        {actions.map(
          ({ attrs: { class: className, ...attrs } = {}, icon, link: href, text, variant }) => (
            <LinkButton {href} {variant} icon={icon?.name} class:list={[className]} {...attrs}>
              {text}
              {icon?.html && <Fragment set:html={icon.html} />}
            </LinkButton>
          ),
        )}
      </div>
    )}
  </div>
</div>

<style>
  @layer starlight.core {
    .hero {
      display: grid;
      grid-template-columns: 100%;
      align-items: center;
      gap: 1rem;
      padding-bottom: 1rem;
    }

    .hero > img,
    .hero > .hero-html {
      object-fit: contain;
      width: min(70%, 20rem);
      height: auto;
      margin-inline: auto;
    }

    .stack {
      flex-direction: column;
      gap: clamp(1.5rem, calc(1.5rem + 1vw), 2rem);
      text-align: center;
    }

    .copy {
      flex-direction: column;
      gap: 1rem;
      align-items: center;
    }

    .copy > * {
      max-width: 50ch;
    }

    .page-eyebrow + h1 {
      margin-top: 0.25rem;
    }

    h1 {
      font-size: clamp(var(--sl-text-3xl), calc(0.25rem + 5vw), var(--sl-text-6xl));
      line-height: var(--sl-line-height-headings);
      color: var(--sl-color-white);
    }

    .tagline {
      color: var(--sl-color-gray-2);
    }

    .actions {
      gap: 1rem 2rem;
      flex-wrap: wrap;
      justify-content: center;
    }

    @media (min-width: 50rem) {
      .hero {
        grid-template-columns: 7fr 4fr;
        gap: 3%;
        padding-block: clamp(2.5rem, calc(1rem + 10vmin), 10rem);
      }

      .hero > img,
      .hero > .hero-html {
        order: 2;
        width: min(100%, 25rem);
      }

      .stack {
        text-align: start;
      }

      .copy {
        align-items: flex-start;
      }

      .actions {
        justify-content: flex-start;
      }
    }
  }
</style>
---
/* The system has exactly two surfaces — warm ebony and cream — so the stock
   three-option auto/light/dark <select> becomes a two-state toggle. The stored
   key and the `data-theme` attribute stay Starlight's, so ThemeProvider's
   no-FOUC inline script keeps working unchanged. */
import { Icon } from '@astrojs/starlight/components';
---

<starlight-theme-select>
  <button type="button" class="theme-toggle">
    <Icon name="moon" class="icon-dark" size="1rem" />
    <Icon name="sun" class="icon-light" size="1rem" />
    <span class="sr-only">{Astro.locals.t('themeSelect.accessibleLabel')}</span>
  </button>
</starlight-theme-select>

<script>
  /** Key in `localStorage` to store colour theme preference at — Starlight's own. */
  const storageKey = 'starlight-theme';

  const currentTheme = (): 'dark' | 'light' =>
    document.documentElement.dataset.theme === 'light' ? 'light' : 'dark';

  class StarlightThemeSelect extends HTMLElement {
    constructor() {
      super();
      const button = this.querySelector('button');
      if (!button) return;
      const label = () => {
        // Name the destination, not the state: this is a control, not a status.
        button.setAttribute(
          'aria-label',
          currentTheme() === 'dark' ? 'Use the light theme' : 'Use the dark theme',
        );
      };
      label();
      button.addEventListener('click', () => {
        const next = currentTheme() === 'dark' ? 'light' : 'dark';
        document.documentElement.dataset.theme = next;
        try {
          localStorage.setItem(storageKey, next);
        } catch {}
        label();
      });
    }
  }
  customElements.define('starlight-theme-select', StarlightThemeSelect);
</script>

<style>
  @layer starlight.core {
    .theme-toggle {
      position: relative;
      display: flex;
      align-items: center;
      justify-content: center;
      width: 2rem;
      height: 2rem;
      padding: 0;
      border: 1px solid var(--sl-color-hairline-light);
      border-radius: var(--bl-radius-1);
      background-color: transparent;
      color: var(--sl-color-gray-2);
      cursor: pointer;
    }

    .theme-toggle:hover {
      background-color: var(--sl-color-gray-6);
      border-color: var(--sl-color-gray-4);
      color: var(--sl-color-white);
    }

    /* 32px box, 44px target. */
    .theme-toggle::after {
      content: '';
      position: absolute;
      inset: -0.375rem;
    }

    /* Show the surface you are on, not the one you would switch to. */
    .icon-light {
      display: none;
    }

    :global(:root[data-theme='light']) .icon-dark {
      display: none;
    }

    :global(:root[data-theme='light']) .icon-light {
      display: block;
    }
  }
</style>
---
// The facts a reader wants before the prose: where a feature is, its keys, what it needs.
// Every prop is optional, and a row appears only when its prop is given.
interface Props {
  /** Menu paths, as the app prints them: `Clip ▸ Split`. */
  menu?: string | string[];
  /** Keys, as the app prints them: `⌘T`. */
  keys?: string | string[];
  /** Where else it lives: an inspector tab and section, the toolbar, a right-click menu. */
  where?: string | string[];
  /** The agent tools that do the same thing. */
  tools?: string | string[];
  /** What it needs beyond the app: a key, a permission, a model. */
  needs?: string | string[];
}

const list = (value?: string | string[]) => (value === undefined ? [] : [value].flat());
const { menu, keys, where, tools, needs } = Astro.props;
---

<dl class="fj-glance not-content">
  {list(menu).length > 0 && (
    <>
      <dt>Menu</dt>
      <dd>
        {list(menu).map((item) => (
          <strong>{item}</strong>
        ))}
      </dd>
    </>
  )}
  {list(keys).length > 0 && (
    <>
      <dt>Keys</dt>
      <dd>
        {list(keys).map((item) => (
          <kbd>{item}</kbd>
        ))}
      </dd>
    </>
  )}
  {list(where).length > 0 && (
    <>
      <dt>Where</dt>
      <dd>
        {list(where).map((item) => (
          <span>{item}</span>
        ))}
      </dd>
    </>
  )}
  {list(needs).length > 0 && (
    <>
      <dt>Needs</dt>
      <dd>
        {list(needs).map((item) => (
          <span>{item}</span>
        ))}
      </dd>
    </>
  )}
  {list(tools).length > 0 && (
    <>
      <dt>Agent tools</dt>
      <dd>
        {list(tools).map((item) => (
          <code>{item}</code>
        ))}
      </dd>
    </>
  )}
</dl>

